#include <vector>
#include <algorithm>

class Solution {
public:
    int solve(const std::vector<int>& input) {
        int n = input.size();
        if (n == 0) return 0;

        // dp[i] stores optimal answer for prefix of length i
        std::vector<int> dp(n + 1, 0);

        for (int i = 1; i <= n; ++i) {
            // Transition: dp[i] = optimal choice from prior states
            dp[i] = dp[i - 1] + input[i - 1];
        }

        return dp[n];
    }
};
